      if (debt) used.push(debt);
      out.push({ id: k, name: String(c.name), bank: String(c.bank || ''), kind: c.kind === 'debit' ? 'debit' : 'credit', debt: debt,
        income: Array.isArray(c.income) ? c.income : [] });
